<?php defined('BASEPATH') or exit('No direct script access allowed'); init_head(); ?><div id="wrapper"><div class="content"><div class="luxcraft-card"><h4>My Payslips</h4><hr><div class="luxcraft-table-responsive"><table class="table dt-table"><thead><tr><th>Month</th><th>Payment Date</th><th>Status</th><th>View</th></tr></thead><tbody><?php foreach($payslips as $p){ ?><tr><td><?php echo luxcraft_format_salary_month($p['salary_month']); ?></td><td><?php echo _d($p['payment_date']); ?></td><td><?php echo ucfirst($p['status']); ?></td><td><a class="btn btn-default btn-sm" href="<?php echo admin_url('luxcraft_payslips/view/'.$p['id']); ?>"><i class="fa fa-eye"></i> View</a></td></tr><?php } ?></tbody></table></div></div></div></div><?php init_tail(); ?>
